changeSet.sql:
create or alter procedure [graph].[Hop_GetBadgeCounts] @diagramType int, @expanded bit, @leafOnly bit as begin
drop table if exists #predicatesToSkip create table #predicatesToSkip (ID int) create index ix_PredicatesToSkip on #predicatesToSkip (ID asc)
if @diagramType = 1 begin insert into #predicatesToSkip values (1),(3),(4),(11),(12)
-- Determine UseAsTransformation update T set T.UseAsTransformation = S.UseAsTransformation, T.IsSubjectInTransformation = CASE WHEN ATO.Cnt = 0 THEN 0 ELSE 1 END from #nodes T inner join AssetType S on S.ID = T.AssetTypeID cross apply ( select count(*) from IntersectType IT left join AssetType ATO on ATO.Object = IT.Object and ATO.ObjectID = IT.ObjectID and ATO.UseAsTransformation = 1 where IT.Subject = S.Object and IT.SubjectID = S.ObjectID ) ATO(Cnt) where T.Parsed = 0; end
-- Get action counts update R set R.ActionCount = coalesce( ( select count(1) as ActionCount from Issue I inner join Asset A on A.Object = I.Object and A.ObjectID = I.ObjectID where I.CompletedOn is null and exists (select 1 from workflow.Item where Object = 'Issue' and ObjectID = I.ID) and A.ID = R.AssetID group by A.Uid ), 0) from #nodes R where R.Parsed = 0 and ( (@leafOnly = 1 and R.IsLeaf = 1) or (@leafOnly = 0) );
-- Get impact badges update R set R.RelationCounts = coalesce( ( select [Predicate], ID as PredicateID, Uid as PredicateUid, Direction, count(1) as [Count], case when @expanded = 1 and @diagramType = 2 then 1 else 0 end as Expanded from ( select P.Name as [Predicate], P.ID, P.Uid, 1 as Direction from graph.AssetNode S, graph.AssetEdge E, graph.AssetNode T, [Predicate] P where MATCH(S-(E)->T) and S.ID = R.AssetID and T.Uid not in (select Uid from #assetsToIgnore) and T.ID not in (select ID from #hopAssets) and P.ID = E.PredicateID and E.PredicateType not in (select ID from #predicatesToSkip) union all select P.Inverse as [Predicate], P.ID, P.Uid, 2 as Direction from graph.AssetNode S, graph.AssetEdge E, graph.AssetNode T, [Predicate] P where MATCH(S-(E)->T) and T.ID = R.AssetID and S.Uid not in (select Uid from #assetsToIgnore) and S.ID not in (select ID from #hopAssets) and P.ID = E.PredicateID and E.PredicateType not in (select ID from #predicatesToSkip) ) O group by [Predicate], ID, Uid, Direction for json path ), '[]' ) from #nodes R where R.Parsed = 0 and ( (@leafOnly = 1 and R.IsLeaf = 1) or (@leafOnly = 0) );
-- Get owner badges update R set R.OwnerCounts = coalesce( ( select ResponsibilityTypeName as ResponsibilityType, ResponsibilityTypeID, '[' + string_Agg(ResourceID, ',') + ']' as UsersList, count(1) as [Count], 0 as Expanded from ( select ResponsibilityTypeName, ResponsibilityTypeID, ResourceID from ResponsibilityDetail where ( AssetID = R.AssetID OR (AssetID = 0 and AssetTypeID = R.AssetTypeID) ) and IsVisible = 1 group by ResponsibilityTypeName, ResponsibilityTypeID, ResourceID ) O group by ResponsibilityTypeName, ResponsibilityTypeID for json path ), '[]' ) from #nodes R where R.Parsed = 0 and ( (@leafOnly = 1 and R.IsLeaf = 1) or (@leafOnly = 0) );
update #nodes set OwnerCounts = '[]', IsLeaf = 0 where IsLeaf is null and Parsed = 0; end
